    /**
     * Tests getting all JobProfiles.
     *
     * @return    Collection
     */
    public List<JobProfile> testGetAll() throws Throwable {
    LOGGER.info( "JobProfileTest:testGetAll() - Retrieving Collection of JobProfiles:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all JobProfile : " );
    List<JobProfile> collection  = null;

    try {
        // call the static get method on the JobProfileService
        collection = service.getAllJobProfile();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            JobProfile currEntity  = null;
            Iterator<JobProfile> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getJobProfileId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

